def compute(vars):
    rental_2018 = vars["v1"]
    total_rentals = vars["v2"]
    if total_rentals == 0:
        return None

    ratio = rental_2018 / total_rentals
    percentage = ratio * 100
    return {
        "value": percentage,
        "trace": {
            "rental_2018": rental_2018,
            "total_rentals": total_rentals,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
